{
  "description": "The creature is shown in right-facing profile against a plain off-white background, standing on four short limbs with its body held low to the ground. It has a stout, elongated trunk with a thick, fleshy tail extending to the left and a broad, flat head at the right end. The entire dorsal surface from the back of the neck to the base of the tail is covered in overlapping, rounded brown scales with darker edges, while the head, throat, belly, limbs, and tail are pale pink, wrinkled, and fleshy with a moist appearance. Behind the head on both sides are multiple feathery pink external gills. The head has large golden eyes with dark pupils, small nostrils, and a wide mouth. The overall form combines a low quadrupedal amphibian body with heavy dorsal armor.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flat and rounded axolotl-like head with a wide mouth, small round nostrils near the snout tip, large protruding golden eyes with black pupils, and mottled dark brown spots on pale pink-tan skin",
      "where": "at the front right end of the body"
    },
    {
      "part": "gills",
      "looks_like": "six to eight fleshy pink stalks with fine feathery filaments along their length, three to four visible on each side of the neck, branching outward and backward",
      "where": "protruding from the sides of the neck immediately behind the head"
    },
    {
      "part": "scales",
      "looks_like": "large overlapping keratinous plates, rounded and slightly pointed, brown with darker brown to black shading at the base and lighter tan edges, arranged in diagonal rows",
      "where": "covering the entire dorsal surface from the back of the neck along the back to the base of the tail"
    },
    {
      "part": "legs",
      "looks_like": "four short, stout, columnar limbs with deeply wrinkled pale pink skin and folded flesh at the joints",
      "where": "underneath the body, two forelegs beneath the chest and two hindlegs beneath the rear, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "broad five-toed feet with short blunt claws/nails on each digit, same wrinkled pink skin as the legs",
      "where": "at the distal end of each of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "thick, fleshy, tapering tail with smooth pale pink wrinkled skin, partially cropped by the left edge of the image",
      "where": "extending from the rear of the body to the left"
    },
    {
      "part": "markings",
      "looks_like": "irregular dark brown to black mottled spots and speckles on the head and around the eyes, and transverse wrinkled folds and creases on the pale ventral skin and limbs",
      "where": "on the dorsal and lateral surfaces of the head, and on the belly, throat, and limbs"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
